  await page.locator('#lesson-frame').evaluate(el=>el.dataset.mounted='yes');
  await page.getByRole('button',{name:'My notes',exact:true}).click();
  await page.getByLabel('Notes for this lesson',{exact:true}).fill('Remember how input becomes information.');
  await page.getByRole('button',{name:'Close notes',exact:true}).click();
  await expect(page.locator('#lesson-frame')).toHaveAttribute('data-mounted','yes');
  await page.getByRole('button',{name:'Next lesson',exact:true}).click();
  await expect(page.getByRole('heading',{name:'1.2 Types of Computers',exact:true})).toBeVisible();
  await page.getByRole('button',{name:'Go back',exact:true}).click();
  await expect(page.getByRole('heading',{name:'1.1 What Is a Computer?',exact:true})).toBeVisible();
  await page.getByRole('button',{name:'Go forward',exact:true}).click();
  await expect(page.getByRole('heading',{name:'1.2 Types of Computers',exact:true})).toBeVisible();
  await page.getByRole('button',{name:'Previous lesson',exact:true}).click();
  await page.getByRole('button',{name:'My notes',exact:true}).click();
  await expect(page.getByLabel('Notes for this lesson',{exact:true})).toHaveValue('Remember how input becomes information.');
  await page.getByRole('button',{name:'Close notes',exact:true}).click();
  await expect(page.locator('#lesson-video')).toHaveCount(1);
  expect(await page.evaluate(()=>document.querySelector('.inline-video').compareDocumentPosition(document.querySelector('#lesson-frame'))&Node.DOCUMENT_POSITION_FOLLOWING)).toBeTruthy();
  await page.screenshot({path:'test-results/07-video-classroom.png',fullPage:true});
  await page.getByRole('button',{name:'Hide video',exact:true}).click();await expect(page.locator('#lesson-video')).toHaveCount(0);
  await page.context().setOffline(true);await page.getByRole('button',{name:'Show video',exact:true}).click();
  await expect(page.getByRole('heading',{name:'You’re offline.'})).toBeVisible();
  await page.context().setOffline(false);await page.getByRole('button',{name:'Try again',exact:true}).click();
  await expect(page.locator('#lesson-video')).toHaveAttribute('src',/youtube-nocookie.com\/embed\/kBGcfVwf9aI/);
  await expect(page.frameLocator('#lesson-video').locator('body')).toContainText('Player boundary verified');
  expect(await page.frameLocator('#lesson-video').locator('body').evaluate(()=>typeof window.tihDesktop)).toBe('undefined');
  await page.locator('#lesson-video').evaluate(el=>el.dataset.mounted='yes');await page.getByRole('button',{name:'My notes',exact:true}).click();await expect(page.locator('#lesson-video')).toHaveAttribute('data-mounted','yes');await page.getByRole('button',{name:'Close notes',exact:true}).click();
  // Wheel and PageDown over the isolated written document scroll the shared lesson pane.
  await page.getByRole('button',{name:'Read the lesson below',exact:true}).click();await expect.poll(()=>page.locator('#pane-read').evaluate(el=>el.scrollTop)).toBeGreaterThan(200);
  const before=await page.locator('#pane-read').evaluate(el=>el.scrollTop);await page.frameLocator('#lesson-frame').locator('main').hover();await page.mouse.wheel(0,300);await expect.poll(()=>page.locator('#pane-read').evaluate(el=>el.scrollTop)).toBeGreaterThan(before+100);
  const afterWheel=await page.locator('#pane-read').evaluate(el=>el.scrollTop);const paneBox=await page.locator('#pane-read').boundingBox();await page.mouse.click(paneBox.x+50,paneBox.y+80);await page.keyboard.press('PageDown');await expect.poll(()=>page.locator('#pane-read').evaluate(el=>el.scrollTop)).toBeGreaterThan(afterWheel);
  expect(await page.frameLocator('#lesson-frame').locator('body').evaluate(()=>typeof window.tihDesktop)).toBe('undefined');await page.screenshot({path:'test-results/13-continuous-reading.png',fullPage:true});
  await page.getByRole('tab',{name:'Resources',exact:true}).click();await expect(page.locator('#lesson-video')).toHaveCount(0);await expect(page.getByRole('heading',{name:'Everything for this lesson'})).toBeVisible();await page.getByRole('tab',{name:'Resources',exact:true}).press('ArrowRight');await expect(page.getByRole('tab',{name:'Lesson',exact:true})).toHaveAttribute('aria-selected','true');
  await page.getByRole('button',{name:'Enter full screen',exact:true}).click();
  await expect.poll(()=>page.evaluate(()=>!!document.fullscreenElement)).toBeTruthy();
  await page.getByRole('button',{name:'Exit full screen',exact:true}).click();
  await expect.poll(()=>page.evaluate(()=>!!document.fullscreenElement)).toBeFalsy();
  await page.getByRole('button',{name:'Next lesson',exact:true}).click();
  await page.getByRole('button',{name:'Overview',exact:true}).click();
  await page.getByRole('button',{name:'Learning space',exact:true}).click();
  await expect(page.getByRole('heading',{name:'1.2 Types of Computers',exact:true})).toBeVisible();
  if(electron){expect(await page.evaluate(()=>window.tihDesktop.openVideo('https://attacker.invalid').then(()=>false,()=>true))).toBeTruthy();}
